static void transferMoney(Connection conn, int fromId, int toId, int amount) throws SQLException {
  conn.setAutoCommit(false);
  try {
    conn.createStatement().executeUpdate("UPDATE accounts SET balance=balance-" + amount + " WHERE id=" + fromId);
    conn.createStatement().executeUpdate("UPDATE accounts SET balance=balance+" + amount + " WHERE id=" + toId);
    conn.commit();
  } catch (SQLException e) { conn.rollback(); throw e; }
  finally { conn.setAutoCommit(true); }
}

