@FunctionalInterface interface TransactionalOperation<T> { T execute(Connection conn) throws SQLException; }
static <T> T runInTransaction(Connection conn, TransactionalOperation<T> op) throws SQLException {
  conn.setAutoCommit(false);
  try { T result = op.execute(conn); conn.commit(); return result; }
  catch (SQLException e) { conn.rollback(); throw e; }
  finally { conn.setAutoCommit(true); }
}

