class TransactionManager {
  <T> T execute(Connection conn, TransactionalOperation<T> op, int maxAttempts) throws SQLException {
    for (int attempt = 1; attempt <= maxAttempts; attempt++) {
      long start = System.nanoTime();
      try {
        T result = runInTransaction(conn, op);
        System.out.println("Czas: " + (System.nanoTime()-start)/1_000_000 + "ms");
        return result;
      } catch (SQLException e) {
        logAudit(conn, "Proba " + attempt + " nieudana: " + e.getMessage());
        if (attempt == maxAttempts) throw e;
      }
    }
    throw new IllegalStateException();
  }
}
